package com.example.notification_service;import com.example.notification_service.event.ApplicationEvent;import com.example.notification_service.service.EmailTemplateService;import org.junit.jupiter.api.Test;import java.time.Instant;import java.util.UUID;import static org.assertj.core.api.Assertions.*;
class EmailTemplateServiceTest{private final EmailTemplateService templates=new EmailTemplateService();@Test void mapsSubmittedAndStatusTemplates(){var data=new ApplicationEvent.Data(UUID.randomUUID(),UUID.randomUUID(),UUID.randomUUID(),UUID.randomUUID(),"candidate@example.com","Engineer",null,"APPLIED","trace");assertThat(templates.render(new ApplicationEvent(UUID.randomUUID(),"APPLICATION_SUBMITTED",1,Instant.now(),"application-service",data)).templateCode()).isEqualTo("APPLICATION_SUBMITTED");var changed=new ApplicationEvent.Data(data.applicationId(),data.jobId(),data.companyId(),data.candidateId(),data.candidateEmail(),data.jobTitle(),"APPLIED","SCREENING","trace");assertThat(templates.render(new ApplicationEvent(UUID.randomUUID(),"APPLICATION_STATUS_CHANGED",1,Instant.now(),"application-service",changed)).body()).contains("APPLIED","SCREENING");}}
